import * as React from "react";
import * as icons from "@iconmind/react";
import { cn } from "@/lib/utils";

/** Every IconMind export, keyed by component name — `Icon name="AgentRun"` or the slug `agent-run`. */
type IconName = keyof typeof icons;
const toName = (s: string) => (s.includes("-") ? s.split("-").map((p) => p[0]!.toUpperCase() + p.slice(1)).join("") : s) as IconName;

export interface IconProps extends React.SVGProps<SVGSVGElement> {
  name: IconName | (string & {});
  /** outline (default) or duotone */
  variant?: "outline" | "duotone";
  /** thin 1.5 · regular 2 · bold 2.5 */
  weight?: "thin" | "regular" | "bold";
  size?: number;
}

export function Icon({ name, variant = "outline", weight = "regular", size = 20, className, ...rest }: IconProps) {
  const Cmp = icons[toName(name)] as React.ComponentType<any> | undefined;
  if (!Cmp) return null;
  return <Cmp variant={variant} weight={weight} size={size} className={cn("shrink-0", className)} aria-hidden {...rest} />;
}
